{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  if (w[0] === 'candidates') {
    if (cands !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = [...seen]
  } else if (w[0] === 'ballot') {
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const known = new Set(cands || [])
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (!known.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const cont = new Set(cands)
const history = []
let out = ''
let result
let roundNo = 0
for (;;) {
  roundNo++
  const counts = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  history.push(counts)
  const order = [...cont].sort((a, b) => (counts.get(a) > counts.get(b) ? -1 : counts.get(a) < counts.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  out += `round ${roundNo}: ${order.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}\n`
  if (active === 0n) { result = 'no winner'; break }
  const win = order.find((c) => counts.get(c) * 2n > active)
  if (win !== undefined) { result = `winner ${win}`; break }
  const min = counts.get(order[order.length - 1])
  let tied = order.filter((c) => counts.get(c) === min)
  while (tied.length > 1) {
    const r = history.find((h) => tied.some((c) => h.get(c) !== h.get(tied[0])))
    if (!r) break
    const m = tied.reduce((a, c) => (r.get(c) < a ? r.get(c) : a), r.get(tied[0]))
    tied = tied.filter((c) => r.get(c) === m)
  }
  const gone = tied.sort().pop()
  cont.delete(gone)
  out += `eliminated ${gone}\n`
}
process.stdout.write(mode === 'rounds' ? `${out}${result}\n` : `rounds ${roundNo}\n${result}\n`)
EOF
node --test test/*.test.js 2>&1 | grep -E "^# (pass|fail)"","description":"Write cli and run tests"}

